import { useEffect, useMemo, useRef, useState, type FormEvent, type ReactNode } from 'react';
import { Archive, ArrowUpRight, BrainCircuit, Bot, Check, ChevronDown, CircleAlert, Download, FileAudio, FileImage, FileText, FileVideo, KeyRound, Library, LockKeyhole, MessageCircle, Mic, Mic2, MoreHorizontal, PanelRight, Play, Plus, RefreshCw, Search, Send, Settings2, ShieldCheck, Sparkles, Trash2, UserPlus, Users, Volume2, Waves, X, XCircle } from 'lucide-react';
import { API_URL, api, assetUrl, streamApi } from './api';
import LiveAvatar from './LiveAvatar';

type Role = 'admin' | 'adult' | 'child';
type PanelMode = 'chat' | 'memories' | 'controls' | 'governance' | 'learning';
type LivePhase = 'off' | 'listening' | 'thinking' | 'speaking';
type BrowserSpeechStream = { push: (chunk: string) => void; finish: (answer: string) => void; cancel: () => void; promise: Promise<void> };
type Member = { id: string; name: string; relationship: string; isDeceased: boolean; posthumousStatus: string };
type Memory = { id: string; title: string; type: string; tags: string[]; transcript?: string; consentStatus: string; processingStatus?: string; createdAt: string; familyMemberId: string; familyMemberName?: string; uploaderName?: string; sourceUrl?: string };
type Consent = { id: string; familyMemberId: string; type: string; grantedAt: string; revokedAt?: string; memberName?: string };
type VoiceModel = { id: string; familyMemberId: string; sourceMemoryId: string; promptText?: string; provider?: string; status: string };
type AppData = { user: { id: string; name: string; email: string; role: Role; familyId: string }; family: { id: string; name: string }; members: Member[]; memories: Memory[]; consents: Consent[]; voiceModels: VoiceModel[]; pendingApprovals: number };
type LlmStatus = { ready: boolean; downloading?: boolean; downloaded?: boolean; progress?: number; model?: string; configuredModel?: string; models?: string[]; provider: string };
type ChatMessage = { role: 'user' | 'assistant'; content: string; sources?: Memory[]; conversational?: boolean; llm?: { model: string; provider: string }; voice?: { audioUrl: string; disclosure: string }; voiceError?: string; avatar?: { disclosure: string } };
type VoiceStatus = { provider: string; configured: boolean; serviceReachable: boolean; ready: boolean; referenceReady: boolean; consentGranted: boolean; modelReady: boolean; message: string; sourceName?: string };
type LearningItem = { id: string; kind: string; title: string; content: string; confidence: number; status: string; familyMemberName?: string; createdAt: string };
type TrainingJob = { id: string; status: string; baseModel: string; datasetPath: string; outputPath: string; sampleCount?: number; error?: string; log?: string; createdAt: string; finishedAt?: string };
type LearningData = { items: LearningItem[]; jobs: TrainingJob[]; threshold: number; pending: number; approved: number };

const typeIcon: Record<string, ReactNode> = { photo: <FileImage size={14} />, video: <FileVideo size={14} />, audio: <FileAudio size={14} />, text: <FileText size={14} />, doc: <FileText size={14} /> };

export default function AiriApp() {
  const [data, setData] = useState<AppData | null>(null); const [loading, setLoading] = useState(true); const [notice, setNotice] = useState('');
  const refresh = async () => { try { setData(await api<AppData>('/bootstrap')); setNotice(''); } catch (error) { localStorage.removeItem('tianai_token'); setData(null); setNotice(error instanceof Error ? error.message : 'Unable to open family space'); } };
  useEffect(() => { if (localStorage.getItem('tianai_token')) refresh().finally(() => setLoading(false)); else setLoading(false); }, []);
  if (loading) return <div className="airi-loading"><div className="airi-loading-orbit"><span /><span /><span /></div><strong>TiānAI</strong><small>initializing memory stage</small></div>;
  if (!data) return <AiriAuth onSuccess={refresh} error={notice} />;
  return <AiriWorkspace data={data} refresh={refresh} />;
}

function AiriAuth({ onSuccess, error }: { onSuccess: () => Promise<void>; error: string }) {
  const [mode, setMode] = useState<'login' | 'register'>('login'); const [form, setForm] = useState({ familyName: '', name: '', email: 'demo@tianai.local', password: 'demo1234' }); const [busy, setBusy] = useState(false); const [message, setMessage] = useState(error);
  const submit = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setMessage(''); try { const result = await api<{ token: string }>(mode === 'login' ? '/auth/login' : '/auth/register-family', { method: 'POST', body: JSON.stringify(form) }); localStorage.setItem('tianai_token', result.token); await onSuccess(); } catch (e) { setMessage(e instanceof Error ? e.message : 'Unable to continue'); } finally { setBusy(false); } };
  return <div className="airi-auth"><div className="airi-auth-noise" /><div className="airi-auth-copy"><div className="airi-logo"><span>✦</span><div><strong>TiānAI</strong><small>memory stage</small></div></div><div className="airi-auth-title"><p className="airi-kicker">CONSENT-FIRST FAMILY AI</p><h1>Your memories,<br /><em>alive with care.</em></h1><p>Step into a private conversational space where every story stays traceable to the person who shared it.</p></div><div className="airi-auth-foot"><span><LockKeyhole size={12} /> local-first</span><span><ShieldCheck size={12} /> source-grounded</span><span><Sparkles size={12} /> AI disclosed</span></div></div><div className="airi-auth-card"><div className="airi-auth-orbit"><div className="airi-auth-orbit-inner"><Bot size={22} /></div></div><p className="airi-kicker">{mode === 'login' ? 'RETURN TO YOUR STAGE' : 'BEGIN A NEW STAGE'}</p><h2>{mode === 'login' ? 'Welcome back' : 'Create your family space'}</h2><p className="airi-subtle">{mode === 'login' ? 'Your family memory room is waiting.' : 'You become the first family administrator.'}</p><div className="airi-auth-tabs"><button className={mode === 'login' ? 'is-active' : ''} onClick={() => setMode('login')}>Sign in</button><button className={mode === 'register' ? 'is-active' : ''} onClick={() => setMode('register')}>Create family</button></div><form onSubmit={submit}>{mode === 'register' && <><label>Family name<input value={form.familyName} onChange={e => setForm({ ...form, familyName: e.target.value })} placeholder="The Chen family" required /></label><label>Your name<input value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} placeholder="Lin Chen" required /></label></>}<label>Email<input value={form.email} onChange={e => setForm({ ...form, email: e.target.value })} type="email" required /></label><label>Password<input value={form.password} onChange={e => setForm({ ...form, password: e.target.value })} type="password" minLength={8} required /></label>{message && <div className="airi-error"><CircleAlert size={14} />{message}</div>}<button className="airi-primary" disabled={busy}>{busy ? 'Opening stage...' : mode === 'login' ? 'Enter memory stage' : 'Create memory stage'}<ArrowUpRight size={16} /></button></form>{mode === 'login' && <div className="airi-demo"><KeyRound size={13} /> demo@tianai.local <span>/</span> demo1234</div>}</div></div>;
}

function AiriWorkspace({ data, refresh }: { data: AppData; refresh: () => Promise<void> }) {
  const [panel, setPanel] = useState<PanelMode>('chat'); const [panelOpen, setPanelOpen] = useState(true); const [memberId, setMemberId] = useState(data.members[0]?.id || ''); const [voiceInput, setVoiceInput] = useState(''); const [listening, setListening] = useState(false); const [voiceNotice, setVoiceNotice] = useState(''); const [llmStatus, setLlmStatus] = useState<LlmStatus>(); const member = data.members.find(item => item.id === memberId) || data.members[0];
  useEffect(() => { if (!memberId && data.members[0]) setMemberId(data.members[0].id); }, [data.members, memberId]);
  useEffect(() => { let active = true; const check = () => api<LlmStatus>('/llm/status').then(status => { if (active) setLlmStatus(status); }).catch(() => { if (active) setLlmStatus(undefined); }); check(); const timer = window.setInterval(check, 15000); return () => { active = false; window.clearInterval(timer); }; }, []);
  const logout = () => { localStorage.removeItem('tianai_token'); window.location.reload(); };
  const selectPanel = (next: PanelMode) => { setPanel(next); setPanelOpen(true); };
  const startVoiceInput = () => { selectPanel('chat'); window.setTimeout(() => window.dispatchEvent(new Event('tianai-live-toggle')), 0); };
  const modelLabel = llmStatus?.ready ? (llmStatus.model || llmStatus.configuredModel || 'local model') : llmStatus?.downloading ? (typeof llmStatus.progress === 'number' && llmStatus.progress >= 0 ? `downloading ${Math.round(llmStatus.progress * 100)}%` : 'downloading model') : llmStatus?.downloaded ? 'local model standby' : 'local model offline';
  const modelState = llmStatus?.ready ? 'is-ready' : llmStatus?.downloading ? 'is-downloading' : llmStatus?.downloaded ? 'is-standby' : 'is-offline';
  return <div className="airi-shell"><section className={`airi-stage ${panelOpen ? 'panel-visible' : ''}`}><div className="airi-backdrop" /><div className="airi-scanlines" /><header className="airi-topbar"><div className="airi-logo"><span>✦</span><div><strong>TiānAI</strong><small>memory stage</small></div></div><div className={`airi-stage-status ${modelState}`}><span className="airi-live-dot" /> {data.family.name}<i /><strong>{modelLabel}</strong></div><div className="airi-top-actions"><button className="airi-icon" onClick={() => selectPanel('governance')} title="Governance"><ShieldCheck size={16} /></button><button className="airi-icon" onClick={() => selectPanel('learning')} title="Learning loop"><BrainCircuit size={16} /></button><button className="airi-icon" onClick={() => selectPanel('controls')} title="Settings"><Settings2 size={16} /></button><button className="airi-icon" onClick={logout} title="Sign out"><MoreHorizontal size={17} /></button></div></header><main className="airi-stage-content"><div className="airi-stage-label"><span className="airi-kicker">MEMORY COMPANION / 01</span><h1>{member?.name || 'Family memory'}</h1><div className="airi-member-select"><span>{member?.relationship || 'profile'} · {data.memories.filter(m => m.familyMemberId === member?.id && m.consentStatus === 'approved').length} approved memories</span><ChevronDown size={14} /><select value={memberId} onChange={e => setMemberId(e.target.value)} aria-label="Select family member">{data.members.map(item => <option key={item.id} value={item.id}>{item.name} · {item.relationship}</option>)}</select></div></div><div className="airi-character-wrap"><div className="airi-character-glow" /><div className="airi-character-rings"><span /><span /><span /></div><LiveAvatar /><div className="airi-character-tag"><span className="airi-live-dot" /> AI AVATAR / LIVE STAGE</div></div><div className="airi-stage-note"><Bot size={14} /><span>Everything spoken here is AI-generated and grounded in approved family memories.</span></div></main><footer className="airi-stage-footer"><div className="airi-footer-status"><span className="airi-pulse" /><span>memory link stable</span></div><div className="airi-footer-center"><button className={panel === 'chat' ? 'is-active' : ''} onClick={() => selectPanel('chat')}><MessageCircle size={15} /> chat</button><button className={panel === 'memories' ? 'is-active' : ''} onClick={() => selectPanel('memories')}><Library size={15} /> vault <b>{data.pendingApprovals || ''}</b></button><button className={panel === 'learning' ? 'is-active' : ''} onClick={() => selectPanel('learning')}><BrainCircuit size={15} /> learn</button><button className={panel === 'controls' ? 'is-active' : ''} onClick={() => selectPanel('controls')}><Waves size={15} /> response</button></div><div className="airi-footer-actions"><button className={`airi-round-control ${listening ? 'is-active' : ''}`} onClick={startVoiceInput} title="Use microphone"><Mic size={16} /></button><button className="airi-round-control" onClick={() => setPanelOpen(!panelOpen)}><PanelRight size={16} /></button></div></footer></section><aside className={`airi-panel ${panelOpen ? 'is-open' : ''}`}>{voiceNotice && <div className="airi-inline-notice"><CircleAlert size={13} />{voiceNotice}</div>}<div className="airi-panel-head"><div><span className="airi-kicker">{panel === 'chat' ? 'LIVE MEMORY CHAT' : panel === 'memories' ? 'MEMORY VAULT' : panel === 'controls' ? 'RESPONSE CONTROL' : panel === 'learning' ? 'SELF LEARNING LOOP' : 'FAMILY GOVERNANCE'}</span><h2>{panel === 'chat' ? `With ${member?.name || 'your family'}` : panel === 'memories' ? 'What is remembered' : panel === 'controls' ? 'Shape the response' : panel === 'learning' ? 'What the agent learned' : 'Consent & access'}</h2></div><button className="airi-icon" onClick={() => setPanelOpen(false)}><X size={17} /></button></div>{panel === 'chat' && <ChatPanel data={data} member={member} voiceInput={voiceInput} />}{panel === 'memories' && <MemoryPanel data={data} refresh={refresh} />}{panel === 'controls' && <ControlPanel data={data} member={member} refresh={refresh} />}{panel === 'learning' && <LearningPanel data={data} member={member} />}{panel === 'governance' && <GovernancePanel data={data} refresh={refresh} />}</aside><nav className="airi-mobile-dock"><button onClick={() => selectPanel('chat')} className={panel === 'chat' ? 'is-active' : ''}><MessageCircle size={17} /><span>chat</span></button><button onClick={() => selectPanel('memories')} className={panel === 'memories' ? 'is-active' : ''}><Library size={17} /><span>vault</span></button><button onClick={() => selectPanel('learning')} className={panel === 'learning' ? 'is-active' : ''}><BrainCircuit size={17} /><span>learn</span></button><button onClick={startVoiceInput} className={panel === 'chat' ? 'is-active' : ''}><Mic size={17} /><span>talk</span></button><button onClick={() => selectPanel('governance')} className={panel === 'governance' ? 'is-active' : ''}><ShieldCheck size={16} /><span>family</span></button></nav></div>;
}

function ChatPanel({ data, member, voiceInput }: { data: AppData; member?: Member; voiceInput?: string }) {
  const [messages, setMessages] = useState<ChatMessage[]>([]); const [text, setText] = useState(''); const [busy, setBusy] = useState(false); const [conversationId, setConversationId] = useState(''); const [voice, setVoice] = useState(false); const [avatar, setAvatar] = useState(false); const [liveVoice, setLiveVoice] = useState(false); const [livePhase, setLivePhase] = useState<'listening' | 'thinking' | 'speaking'>('listening'); const [notice, setNotice] = useState(''); const [voiceStatus, setVoiceStatus] = useState<VoiceStatus>();
  const recognitionRef = useRef<any>(); const liveVoiceRef = useRef(false); const liveToggleRef = useRef<() => void>(() => undefined); const browserSpeechRef = useRef<BrowserSpeechStream>(); const responseInFlightRef = useRef(false); const audioPendingRef = useRef(false); const audioContextRef = useRef<AudioContext>(); const audioScheduleRef = useRef(0); const audioSourcesRef = useRef(new Set<AudioBufferSourceNode>()); const voiceStreamAbortRef = useRef<AbortController>();
  useEffect(() => { setMessages([]); setConversationId(''); }, [member?.id]);
  useEffect(() => { if (voiceInput) setText(voiceInput); }, [voiceInput]);
  useEffect(() => { let active = true; if (!member) return; api<VoiceStatus>(`/voice/status?memberId=${encodeURIComponent(member.id)}`).then(status => { if (active) setVoiceStatus(status); }).catch(() => { if (active) setVoiceStatus(undefined); }); return () => { active = false; }; }, [member?.id]);
  useEffect(() => () => { liveVoiceRef.current = false; audioPendingRef.current = false; recognitionRef.current?.stop(); browserSpeechRef.current?.cancel(); browserSpeechRef.current = undefined; voiceStreamAbortRef.current?.abort(); window.speechSynthesis?.cancel(); audioSourcesRef.current.forEach(source => { try { source.stop(); } catch {} }); audioSourcesRef.current.clear(); void audioContextRef.current?.close(); }, [member?.id]);
  useEffect(() => { const handleLiveToggle = () => liveToggleRef.current(); window.addEventListener('tianai-live-toggle', handleLiveToggle); return () => window.removeEventListener('tianai-live-toggle', handleLiveToggle); }, []);
  useEffect(() => { document.documentElement.dataset.tianaiVoicePhase = liveVoice ? livePhase : 'off'; return () => { delete document.documentElement.dataset.tianaiVoicePhase; }; }, [liveVoice, livePhase]);
  const voiceReady = data.user.role !== 'child' && Boolean(voiceStatus?.ready);
  const restartRecognition = () => { if (liveVoiceRef.current && !responseInFlightRef.current && !audioPendingRef.current) window.setTimeout(() => { if (!liveVoiceRef.current || responseInFlightRef.current || audioPendingRef.current) return; try { recognitionRef.current?.start(); } catch { /* browser is already listening */ } }, 250); };
  const streamVoice = async (answer: string) => {
    const token = localStorage.getItem('tianai_token'); const controller = new AbortController(); let energyFrame = 0; voiceStreamAbortRef.current = controller;
    try {
      const response = await fetch(`${API_URL}/voice/stream`, { method: 'POST', signal: controller.signal, headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}) }, body: JSON.stringify({ familyMemberId: member?.id, text: answer }) });
      if (!response.ok) { let detail = ''; try { const payload = await response.json() as { error?: string }; detail = payload.error || ''; } catch {} throw new Error(detail || 'Live voice could not start'); }
      if (!response.body) throw new Error('Live voice returned no audio stream');
      const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext; if (!AudioContextClass) throw new Error('Live audio is unavailable in this browser.');
      const context = audioContextRef.current || new AudioContextClass(); audioContextRef.current = context; await context.resume();
      const sampleRate = Number(response.headers.get('X-Audio-Sample-Rate')) || 22050; const reader = response.body.getReader(); let pending = new Uint8Array(0); let scheduledUntil = Math.max(context.currentTime + 0.04, audioScheduleRef.current); let playbackFinished: Promise<void> | undefined; const analyser = context.createAnalyser(); analyser.fftSize = 256; const energyData = new Uint8Array(analyser.fftSize); const updateEnergy = () => { analyser.getByteTimeDomainData(energyData); let sum = 0; for (const sample of energyData) { const normalized = (sample - 128) / 128; sum += normalized * normalized; } document.documentElement.style.setProperty('--airi-voice-energy', Math.min(1, Math.sqrt(sum / energyData.length) * 4).toFixed(3)); energyFrame = window.requestAnimationFrame(updateEnergy); }; analyser.connect(context.destination); updateEnergy();
      while (true) {
        const { done, value } = await reader.read(); if (done) break;
        if (value?.length) { const merged = new Uint8Array(pending.length + value.length); merged.set(pending); merged.set(value, pending.length); pending = merged; }
        const usableBytes = pending.length - (pending.length % 2); if (!usableBytes) continue;
        const frames = usableBytes / 2; const buffer = context.createBuffer(1, frames, sampleRate); const channel = buffer.getChannelData(0); const view = new DataView(pending.buffer, pending.byteOffset, usableBytes);
        for (let index = 0; index < frames; index += 1) channel[index] = Math.max(-1, Math.min(1, view.getInt16(index * 2, true) / 32768));
        const source = context.createBufferSource(); source.buffer = buffer; source.connect(analyser); audioSourcesRef.current.add(source); playbackFinished = new Promise(resolve => { source.onended = () => { audioSourcesRef.current.delete(source); resolve(); }; });
        const startAt = Math.max(scheduledUntil, context.currentTime + 0.02); source.start(startAt); scheduledUntil = startAt + buffer.duration; audioScheduleRef.current = scheduledUntil; pending = pending.slice(usableBytes);
      }
      audioScheduleRef.current = scheduledUntil;
      if (playbackFinished) await Promise.race([playbackFinished, new Promise<void>(resolve => controller.signal.addEventListener('abort', () => resolve(), { once: true }))]);
    } finally { if (energyFrame) window.cancelAnimationFrame(energyFrame); if (voiceStreamAbortRef.current === controller) voiceStreamAbortRef.current = undefined; document.documentElement.style.setProperty('--airi-voice-energy', '0'); }
  };
  const speakInBrowser = (answer: string) => new Promise<void>((resolve, reject) => {
    const synthesis = window.speechSynthesis;
    if (!synthesis || typeof window.SpeechSynthesisUtterance === 'undefined') { reject(new Error('Live voice is unavailable in this browser. Use Chrome or Edge for spoken replies.')); return; }
    synthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(answer);
    utterance.lang = navigator.language || 'en-US'; utterance.rate = 0.96; utterance.pitch = 1;
    utterance.onstart = () => { setLivePhase('speaking'); document.documentElement.style.setProperty('--airi-voice-energy', '0.72'); };
    utterance.onend = () => { document.documentElement.style.setProperty('--airi-voice-energy', '0'); resolve(); };
    utterance.onerror = event => reject(new Error(event.error || 'Browser voice could not play'));
    synthesis.speak(utterance);
  });
  const createBrowserSpeechStream = (): BrowserSpeechStream | undefined => {
    const synthesis = window.speechSynthesis;
    if (!synthesis || typeof window.SpeechSynthesisUtterance === 'undefined') return undefined;
    synthesis.cancel();
    let buffer = ''; let streamed = ''; let finished = false; let active = false; let cancelled = false; let settled = false; let energyTimer: number | undefined;
    const queue: string[] = [];
    let resolvePromise: () => void = () => undefined; let rejectPromise: (error: unknown) => void = () => undefined;
    const promise = new Promise<void>((resolve, reject) => { resolvePromise = resolve; rejectPromise = reject; });
    const settle = () => { if (!settled) { settled = true; resolvePromise(); } };
    const fail = (error: unknown) => { if (!settled) { settled = true; rejectPromise(error); } };
    const fillQueue = (force = false) => {
      while (buffer) {
        const boundary = /[.!?](?:["')\]]+)?(?:\s|$)/.exec(buffer);
        if (!boundary) { if (force && buffer.trim()) { queue.push(buffer.trim()); buffer = ''; } break; }
        const end = boundary.index + boundary[0].length; queue.push(buffer.slice(0, end).trim()); buffer = buffer.slice(end);
      }
    };
    const speakNext = () => {
      if (cancelled || active) return;
      const next = queue.shift();
      if (!next) { if (finished) settle(); return; }
      active = true;
      const utterance = new SpeechSynthesisUtterance(next);
      utterance.lang = navigator.language || 'en-US'; utterance.rate = 0.98; utterance.pitch = 1;
      utterance.onstart = () => { setLivePhase('speaking'); document.documentElement.style.setProperty('--airi-voice-energy', '0.72'); energyTimer = window.setInterval(() => { const beat = Math.floor(Date.now() / 90); document.documentElement.style.setProperty('--airi-voice-energy', (0.24 + ((beat * 17) % 68) / 100).toFixed(3)); }, 90); };
      utterance.onend = () => { active = false; if (energyTimer) window.clearInterval(energyTimer); energyTimer = undefined; document.documentElement.style.setProperty('--airi-voice-energy', '0.18'); speakNext(); };
      utterance.onerror = event => { active = false; if (energyTimer) window.clearInterval(energyTimer); energyTimer = undefined; if (cancelled || event.error === 'canceled' || event.error === 'interrupted') settle(); else fail(new Error(event.error || 'Browser voice could not play')); };
      synthesis.speak(utterance);
    };
    return {
      push: chunk => { if (cancelled || !chunk) return; buffer += chunk; streamed += chunk; fillQueue(); speakNext(); },
      finish: answer => { if (cancelled) return; finished = true; if (answer && answer.startsWith(streamed)) buffer += answer.slice(streamed.length); fillQueue(true); speakNext(); },
      cancel: () => { cancelled = true; if (energyTimer) window.clearInterval(energyTimer); energyTimer = undefined; synthesis.cancel(); document.documentElement.style.setProperty('--airi-voice-energy', '0'); settle(); },
      promise,
    };
  };
  const sendQuestion = async (question: string) => {
    if (!question.trim() || !member || busy || responseInFlightRef.current) return;
    recognitionRef.current?.stop(); responseInFlightRef.current = true; if (liveVoiceRef.current) setLivePhase('thinking');
    setText(''); setNotice(''); setMessages(prev => [...prev, { role: 'user', content: question.trim() }, { role: 'assistant', content: '' }]); setBusy(true);
    const liveReply = liveVoiceRef.current; const browserSpeech = liveReply && !voiceReady ? createBrowserSpeechStream() : undefined; if (browserSpeech) { browserSpeechRef.current = browserSpeech; audioPendingRef.current = true; void browserSpeech.promise.catch(() => undefined); }
    try {
      const result = await streamApi<any>('/chat/query/stream', { familyMemberId: member.id, message: question.trim(), conversationId: conversationId || undefined, includeVoice: voice && !liveReply, includeAvatar: avatar, live: liveReply }, delta => { setMessages(prev => prev.map((item, index) => index === prev.length - 1 ? { ...item, content: item.content + delta } : item)); browserSpeech?.push(delta); });
      audioPendingRef.current = Boolean(result.voice) || liveReply; setConversationId(result.conversationId); setMessages(prev => prev.map((item, index) => index === prev.length - 1 ? { role: 'assistant', content: result.answer, sources: result.sources, conversational: result.conversational, llm: result.llm, voice: result.voice, voiceError: result.voiceError, avatar: result.avatar } : item));
      if (liveReply) {
        if (browserSpeech) {
          browserSpeech.finish(result.answer);
          void browserSpeech.promise.catch(error => { if (error?.name !== 'AbortError') setNotice(error instanceof Error ? error.message : 'Live voice could not play'); }).finally(() => { if (browserSpeechRef.current === browserSpeech) browserSpeechRef.current = undefined; audioPendingRef.current = false; setLivePhase('listening'); restartRecognition(); });
        } else {
          setLivePhase('speaking'); const playback = voiceReady ? streamVoice(result.answer).catch(error => { if (error?.name === 'AbortError') throw error; setNotice('Cloned voice could not play; using the default browser voice.'); return speakInBrowser(result.answer); }) : speakInBrowser(result.answer); void playback.catch(error => { if (error?.name !== 'AbortError') setNotice(error instanceof Error ? error.message : 'Live voice could not play'); }).finally(() => { audioPendingRef.current = false; setLivePhase('listening'); restartRecognition(); });
        }
      }
      if ((voice && !liveReply) && result.voiceError) setNotice(result.voiceError); if (avatar && !result.avatar && !result.voiceError) setNotice('Avatar needs both voice and avatar consent.');
    } catch (error) { browserSpeech?.cancel(); if (browserSpeech) { browserSpeechRef.current = undefined; audioPendingRef.current = false; } setNotice(error instanceof Error ? error.message : 'Unable to answer'); }
    finally { if (!browserSpeech) browserSpeechRef.current = undefined; setBusy(false); responseInFlightRef.current = false; restartRecognition(); }
  };
  const send = (event: FormEvent) => { event.preventDefault(); void sendQuestion(text); };
  const stopLiveVoice = () => { liveVoiceRef.current = false; responseInFlightRef.current = false; audioPendingRef.current = false; recognitionRef.current?.stop(); browserSpeechRef.current?.cancel(); browserSpeechRef.current = undefined; voiceStreamAbortRef.current?.abort(); window.speechSynthesis?.cancel(); audioSourcesRef.current.forEach(source => { try { source.stop(); } catch {} }); audioSourcesRef.current.clear(); audioScheduleRef.current = 0; document.documentElement.style.setProperty('--airi-voice-energy', '0'); setLivePhase('listening'); setLiveVoice(false); };
  const startLiveVoice = () => {
    const Recognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!Recognition) { setNotice('Live voice is unavailable in this browser. Use Chrome or Edge for microphone conversation.'); return; }
    const recognition = new Recognition();
    recognition.lang = navigator.language || 'en-US'; recognition.continuous = true; recognition.interimResults = true; recognition.maxAlternatives = 1;
    recognition.onresult = (event: any) => { let transcript = ''; for (let i = event.resultIndex; i < event.results.length; i += 1) if (event.results[i].isFinal) transcript += ` ${event.results[i][0].transcript}`; if (transcript.trim()) void sendQuestion(transcript); };
    recognition.onerror = (event: any) => { if (event.error === 'not-allowed' || event.error === 'service-not-allowed') { liveVoiceRef.current = false; setLiveVoice(false); setNotice('Microphone permission is required for live voice.'); } else if (event.error !== 'aborted' && event.error !== 'no-speech') setNotice('Microphone recognition stopped. Check browser microphone permission.'); };
    recognition.onend = () => { if (liveVoiceRef.current && !responseInFlightRef.current && !audioPendingRef.current) restartRecognition(); else if (!liveVoiceRef.current) setLiveVoice(false); };
    recognitionRef.current = recognition; liveVoiceRef.current = true; setLiveVoice(true); setLivePhase('listening'); setVoice(true); setNotice(''); recognition.start();
  };
  const toggleLiveVoice = () => liveVoice ? stopLiveVoice() : startLiveVoice();
  liveToggleRef.current = toggleLiveVoice;
  const finishAudio = () => { audioPendingRef.current = false; restartRecognition(); };
  return <div className="airi-panel-body airi-chat-panel"><div className="airi-chat-banner"><Bot size={14} /><span>AI-generated · memory grounded when available</span><span className="airi-mini-lock"><LockKeyhole size={11} /></span></div><div className="airi-messages">{!messages.length && <div className="airi-chat-empty"><div className="airi-empty-orbit"><Sparkles size={17} /></div><h3>Ask the memory</h3><p>Try a tradition, a place, or a favorite moment. I will answer naturally and bring in personal details when they matter.</p><div className="airi-prompts"><button onClick={() => setText('What traditions do you remember?')}>traditions</button><button onClick={() => setText('Tell me about a favorite morning.')}>favorite morning</button></div></div>}{messages.map((message, index) => <div className={`airi-message ${message.role}`} key={`${index}-${message.content.slice(0, 10)}`}><div className="airi-message-meta">{message.role === 'assistant' ? <><Bot size={11} /> {message.conversational ? 'conversation' : 'memory companion'}</> : 'you'}</div><p>{message.content || <span className="airi-typing"><i /><i /><i /></span>}</p>{message.voice && <div className="airi-audio"><Volume2 size={13} /><span>{message.voice.disclosure}</span><audio controls autoPlay onEnded={finishAudio} onError={finishAudio} src={assetUrl(message.voice.audioUrl)} /></div>}{message.voiceError && <div className="airi-no-source"><CircleAlert size={12} /> {message.voiceError}</div>}{message.avatar && <div className="airi-avatar-state"><span className="airi-avatar-bars"><i /><i /><i /></span>{message.avatar.disclosure}</div>}</div>)}</div>{notice && <div className="airi-inline-notice"><CircleAlert size={13} />{notice}</div>}<div className="airi-chat-options"><Toggle label="voice response" icon={<Volume2 size={13} />} value={voice} disabled={data.user.role === 'child' || !voiceReady} onChange={setVoice} /><Toggle label="talking avatar" icon={<Waves size={13} />} value={avatar} disabled={data.user.role === 'child' || !voiceReady} onChange={setAvatar} /><button className={`airi-live-voice ${liveVoice ? 'is-active' : ''}`} disabled={data.user.role === 'child'} onClick={toggleLiveVoice} title={liveVoice ? 'Stop live voice' : 'Start live voice'}><Mic size={13} /><span>{liveVoice ? 'live voice on' : 'live voice'}</span></button></div>{data.user.role !== 'child' && !voiceReady && <div className="airi-voice-status"><Volume2 size={12} /> Live mode uses the default browser voice. Connect a consented cloned voice in response controls for custom speech.</div>}{liveVoice && <div className="airi-live-status"><span className="airi-live-status-dot" /> {livePhase === 'thinking' ? 'thinking...' : livePhase === 'speaking' ? 'speaking...' : 'listening...'}</div>}<form className="airi-composer" onSubmit={send}><textarea value={text} onChange={e => setText(e.target.value)} onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send(e); } }} placeholder="Say something to the memory..." rows={1} /><button disabled={busy || !text.trim()}>{busy ? <RefreshCw className="airi-spin" size={16} /> : <Send size={15} />}</button></form></div>;
}

function Toggle({ label, icon, value, disabled, onChange }: { label: string; icon: ReactNode; value: boolean; disabled?: boolean; onChange: (value: boolean) => void }) { return <label className={`airi-toggle ${disabled ? 'is-disabled' : ''}`}><span className="airi-toggle-icon">{icon}</span><span>{label}</span><input type="checkbox" checked={value} disabled={disabled} onChange={e => onChange(e.target.checked)} /><i /></label>; }

function MemoryPanel({ data, refresh }: { data: AppData; refresh: () => Promise<void> }) {
  const [form, setForm] = useState({ familyMemberId: data.members[0]?.id || '', type: 'text', title: '', tags: '', text: '' }); const [file, setFile] = useState<File>(); const [search, setSearch] = useState(''); const [busy, setBusy] = useState(false); const [message, setMessage] = useState('');
  const memories = data.memories.filter(memory => `${memory.title} ${memory.familyMemberName} ${memory.tags.join(' ')}`.toLowerCase().includes(search.toLowerCase()));
  const upload = async (event: FormEvent) => { event.preventDefault(); setBusy(true); try { const body = new FormData(); Object.entries(form).forEach(([key, value]) => body.append(key, value)); if (file) body.append('file', file); await api('/memories', { method: 'POST', body }); setMessage('Queued for administrator approval.'); setForm({ ...form, title: '', tags: '', text: '' }); setFile(undefined); await refresh(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Upload failed'); } finally { setBusy(false); } };
  const decide = async (id: string, action: string) => { try { await api(`/memories/${id}/${action}`, { method: 'POST' }); await refresh(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Action failed'); } };
  const remove = async (id: string) => { if (!window.confirm('Delete this memory, embeddings, and dependent voice data?')) return; try { await api(`/memories/${id}`, { method: 'DELETE' }); await refresh(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Delete failed'); } };
  return <div className="airi-panel-body airi-vault-panel"><div className="airi-panel-stat"><span><Archive size={13} /> {data.memories.filter(m => m.consentStatus === 'approved').length} approved</span><span className={data.pendingApprovals ? 'is-warm' : ''}><span className="airi-live-dot" /> {data.pendingApprovals} pending</span></div><div className="airi-search"><Search size={14} /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search memories" /></div>{data.user.role !== 'child' && <form className="airi-upload-box" onSubmit={upload}><div className="airi-upload-head"><span><Plus size={14} /> add memory</span><small>pending by default</small></div><select value={form.familyMemberId} onChange={e => setForm({ ...form, familyMemberId: e.target.value })}>{data.members.map(member => <option key={member.id} value={member.id}>{member.name}</option>)}</select><div className="airi-upload-row"><select value={form.type} onChange={e => setForm({ ...form, type: e.target.value })}><option value="text">written</option><option value="photo">photo</option><option value="audio">audio</option><option value="video">video</option><option value="doc">document</option></select><input value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} placeholder="title" required /></div><textarea value={form.text} onChange={e => setForm({ ...form, text: e.target.value })} placeholder="Story or transcript..." rows={3} /><label className="airi-file"><input type="file" onChange={e => setFile(e.target.files?.[0])} /><FileText size={13} /> {file?.name || 'attach source file'}</label>{message && <div className="airi-inline-notice">{message}</div>}<button className="airi-primary" disabled={busy}>{busy ? 'processing...' : 'upload for review'}<ArrowUpRight size={14} /></button></form>}{memories.map(memory => <div className="airi-memory-row" key={memory.id}><div className={`airi-memory-icon ${memory.type}`}>{typeIcon[memory.type]}</div><div className="airi-memory-copy"><strong>{memory.title}</strong><span>{memory.familyMemberName} · {new Date(memory.createdAt).toLocaleDateString()}</span><p>{memory.transcript?.slice(0, 100) || (memory.processingStatus === 'needs_processor' ? 'Needs a local OCR or speech processor.' : 'Source file awaiting processing.')}</p></div><div className="airi-memory-actions"><Status status={memory.consentStatus} />{data.user.role === 'admin' && memory.consentStatus === 'pending' && <><button onClick={() => decide(memory.id, 'approve')} title="approve"><Check size={13} /></button><button onClick={() => decide(memory.id, 'reject')} title="reject"><XCircle size={13} /></button></>}<button onClick={() => remove(memory.id)} title="delete"><Trash2 size={13} /></button></div></div>)}{!memories.length && <div className="airi-no-results"><Archive size={20} /><span>No memories match this search.</span></div>}</div>;
}

function LearningPanel({ data, member }: { data: AppData; member?: Member }) {
  const [learning, setLearning] = useState<LearningData>(); const [message, setMessage] = useState(''); const [busy, setBusy] = useState(false);
  const load = async () => { try { setLearning(await api<LearningData>('/learning')); } catch (error) { setMessage(error instanceof Error ? error.message : 'Unable to load learning state'); } };
  useEffect(() => { void load(); }, []);
  const retrain = async () => { setBusy(true); setMessage(''); try { const job = await api<TrainingJob>('/learning/retrain', { method: 'POST' }); setMessage(`Training job ${job.id.slice(0, 8)} started.`); await load(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Unable to start training'); } finally { setBusy(false); } };
  const exportData = async () => { try { const token = localStorage.getItem('tianai_token'); const response = await fetch(`${API_URL}/learning/export`, { headers: token ? { Authorization: `Bearer ${token}` } : {} }); if (!response.ok) throw new Error('Unable to export training data'); const blob = await response.blob(); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = 'tianai-learning.jsonl'; anchor.click(); URL.revokeObjectURL(url); } catch (error) { setMessage(error instanceof Error ? error.message : 'Unable to export training data'); } };
  const approved = learning?.items.filter(item => item.status === 'approved' && (!member || item.familyMemberName === member.name)) || [];
  if (data.user.role === 'child') return <div className="airi-panel-body airi-learning-panel"><div className="airi-empty-orbit"><BrainCircuit size={17} /></div><h3>Learning is private</h3><p>The local learning loop is hidden from child accounts.</p></div>;
  const threshold = learning?.threshold || 20; const remaining = Math.max(0, threshold - approved.length);
  const isAdmin = data.user.role === 'admin';
  return <div className="airi-panel-body airi-learning-panel"><div className="airi-learning-summary"><div><span className="airi-control-label">ACTIVE LEARNINGS</span><strong>{approved.length}</strong></div><div><span className="airi-control-label">NEXT RETRAIN</span><strong>{remaining ? remaining : 'ready'}</strong></div></div><p className="airi-hint">The reviewer learns durable facts, style, boundaries, and skills after each chat. New items become active automatically. Every {threshold} approved examples, TiānAI starts a local LoRA retraining job.</p>{isAdmin && <div className="airi-learning-actions"><button className="airi-secondary" onClick={exportData}><Download size={13} /> export JSONL</button><button className="airi-primary" disabled={busy || approved.length < threshold} onClick={retrain}><Play size={13} /> {busy ? 'starting...' : 'start now'}</button></div>}{message && <div className="airi-inline-notice"><CircleAlert size={13} />{message}</div>}<div className="airi-learning-section"><span className="airi-control-label">ACTIVE PROFILE</span>{approved.length ? approved.map(item => <div className="airi-learning-card is-approved" key={item.id}><div><strong>{item.title}</strong><span>{item.kind} · {item.familyMemberName} · {Math.round(item.confidence * 100)}%</span><p>{item.content}</p></div></div>) : <p className="airi-hint">No durable learning has been recorded yet. Have a few grounded conversations to build the profile.</p>}</div>{learning?.jobs.slice(0, 3).map(job => <div className="airi-learning-job" key={job.id}><span className={`airi-status ${job.status === 'completed' ? 'is-green' : job.status === 'failed' ? 'is-red' : 'is-warm'}`}><i />{job.status}</span><span>{job.baseModel} · {job.sampleCount || '?'} samples</span>{job.error && <small>{job.error}</small>}</div>)}</div>;
}

function ControlPanel({ data, member, refresh }: { data: AppData; member?: Member; refresh: () => Promise<void> }) {
  const [voice, setVoice] = useState(false); const [avatar, setAvatar] = useState(false); const [message, setMessage] = useState(''); const [promptText, setPromptText] = useState(''); const [voiceStatus, setVoiceStatus] = useState<VoiceStatus>(); const consent = (type: string) => data.consents.find(item => item.familyMemberId === member?.id && item.type === type && !item.revokedAt); const model = data.voiceModels.find(item => item.familyMemberId === member?.id && item.status === 'active'); const audioSource = data.memories.find(item => item.familyMemberId === member?.id && item.consentStatus === 'approved' && item.type === 'audio');
  useEffect(() => { setPromptText(model?.promptText || audioSource?.transcript || ''); }, [model?.id, audioSource?.id, audioSource?.transcript]);
  useEffect(() => { let active = true; if (!member) return; api<VoiceStatus>(`/voice/status?memberId=${encodeURIComponent(member.id)}`).then(status => { if (active) setVoiceStatus(status); }).catch(() => { if (active) setVoiceStatus(undefined); }); return () => { active = false; }; }, [member?.id, data.voiceModels.length, data.consents.length, data.memories.length]);
  const grant = async (type: string) => { if (!member) return; setMessage(''); try { await api('/governance/consents', { method: 'POST', body: JSON.stringify({ familyMemberId: member.id, type, legalBasis: type === 'posthumous' ? 'Family administrator authorization' : undefined }) }); await refresh(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Unable to save consent'); } };
  const revoke = async (id: string) => { setMessage(''); try { await api(`/governance/consents/${id}`, { method: 'DELETE' }); await refresh(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Unable to revoke consent'); } };
  const createVoice = async () => { if (!member || !audioSource) return; setMessage(''); try { await api('/voice-models', { method: 'POST', body: JSON.stringify({ familyMemberId: member.id, sourceMemoryId: audioSource.id, promptText }) }); await refresh(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Unable to create voice model'); } };
  const deleteVoice = async () => { if (!model) return; setMessage(''); try { await api(`/voice-models/${model.id}`, { method: 'DELETE' }); await refresh(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Unable to delete voice model'); } };
  const voiceReady = data.user.role !== 'child' && Boolean(voiceStatus?.ready);
  return <div className="airi-panel-body airi-control-panel"><div className="airi-profile-chip"><div className="airi-profile-avatar">{member?.name.charAt(0) || '?'}</div><div><strong>{member?.name}</strong><span>{member?.relationship} · {member?.posthumousStatus}</span></div></div>{message && <div className="airi-inline-notice"><CircleAlert size={13} />{message}</div>}<div className={`airi-voice-readiness ${voiceReady ? 'is-ready' : ''}`}><div><Volume2 size={15} /><strong>{voiceStatus?.provider || 'voice provider'}</strong></div><span>{voiceStatus?.message || 'Checking voice setup...'}</span></div><div className="airi-control-section"><span className="airi-control-label">OUTPUT CHANNELS</span><Toggle label="synthesized voice" icon={<Volume2 size={13} />} value={voice} disabled={data.user.role === 'child' || !voiceReady} onChange={setVoice} /><Toggle label="talking avatar" icon={<Waves size={13} />} value={avatar} disabled={data.user.role === 'child' || !voiceReady} onChange={setAvatar} /></div><div className="airi-control-section"><span className="airi-control-label">STORED CONSENT</span><ConsentRow label="voice consent" active={Boolean(consent('voice'))} onGrant={() => grant('voice')} onRevoke={() => consent('voice') && revoke(consent('voice')!.id)} /><ConsentRow label="avatar consent" active={Boolean(consent('avatar'))} onGrant={() => grant('avatar')} onRevoke={() => consent('avatar') && revoke(consent('avatar')!.id)} /><ConsentRow label="posthumous use" active={Boolean(consent('posthumous'))} onGrant={() => grant('posthumous')} onRevoke={() => consent('posthumous') && revoke(consent('posthumous')!.id)} /></div><div className="airi-control-section"><span className="airi-control-label">VOICE MODEL</span>{audioSource && !model && <label className="airi-prompt-field">Exact words in the recording<textarea value={promptText} onChange={e => setPromptText(e.target.value)} placeholder="Transcribe exactly what is spoken in the reference audio" rows={3} /></label>}{model ? <button className="airi-danger-action" onClick={deleteVoice}><Trash2 size={13} /> delete consented model</button> : <button className="airi-secondary" disabled={!consent('voice') || !audioSource || !promptText.trim() || !voiceStatus?.configured || !voiceStatus.serviceReachable} onClick={createVoice}><Mic2 size={13} /> create from approved audio</button>}<p className="airi-hint"><LockKeyhole size={12} /> {audioSource ? 'Use a clear 10–30 second recording with one speaker. The transcript must match the spoken words.' : 'Upload and approve an audio recording before creating a voice model.'}</p></div></div>;
}

function GovernancePanel({ data, refresh }: { data: AppData; refresh: () => Promise<void> }) {
  const [form, setForm] = useState({ name: '', relationship: '', isDeceased: false }); const [invite, setInvite] = useState({ name: '', email: '', role: 'adult' }); const [message, setMessage] = useState('');
  const add = async (event: FormEvent) => { event.preventDefault(); try { await api('/family/members', { method: 'POST', body: JSON.stringify(form) }); setForm({ name: '', relationship: '', isDeceased: false }); await refresh(); } catch (error) { setMessage(error instanceof Error ? error.message : 'Unable to add profile'); } };
  const sendInvite = async (event: FormEvent) => { event.preventDefault(); try { const result = await api<{ email: string; temporaryPassword: string }>('/family/invites', { method: 'POST', body: JSON.stringify(invite) }); setMessage(`${result.email} invited. Temporary password: ${result.temporaryPassword}`); setInvite({ name: '', email: '', role: 'adult' }); } catch (error) { setMessage(error instanceof Error ? error.message : 'Unable to invite account'); } };
  const consent = async (memberId: string, type: string) => { try { await api('/governance/consents', { method: 'POST', body: JSON.stringify({ familyMemberId: memberId, type }) }); await refresh(); } catch {} };
  return <div className="airi-panel-body airi-governance-panel"><div className="airi-governance-head"><Users size={15} /><span>{data.members.length} profiles · admin controls</span></div>{data.members.map(member => <div className="airi-governance-row" key={member.id}><div className="airi-profile-avatar">{member.name.charAt(0)}</div><div><strong>{member.name}</strong><span>{member.relationship}</span></div><div className="airi-consent-dots"><i className={data.consents.some(c => c.familyMemberId === member.id && c.type === 'voice' && !c.revokedAt) ? 'is-on' : ''} title="voice" /><i className={data.consents.some(c => c.familyMemberId === member.id && c.type === 'avatar' && !c.revokedAt) ? 'is-on' : ''} title="avatar" /><i className={data.consents.some(c => c.familyMemberId === member.id && c.type === 'posthumous' && !c.revokedAt) ? 'is-on' : ''} title="posthumous" /></div></div>)}{data.user.role === 'admin' && <><form className="airi-compact-form" onSubmit={add}><span className="airi-control-label">NEW PROFILE</span><input value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} placeholder="name" required /><input value={form.relationship} onChange={e => setForm({ ...form, relationship: e.target.value })} placeholder="relationship" required /><button className="airi-secondary"><Plus size={13} /> profile</button></form><form className="airi-compact-form" onSubmit={sendInvite}><span className="airi-control-label">INVITE ACCOUNT</span><input value={invite.name} onChange={e => setInvite({ ...invite, name: e.target.value })} placeholder="name" required /><input value={invite.email} onChange={e => setInvite({ ...invite, email: e.target.value })} placeholder="email" type="email" required /><select value={invite.role} onChange={e => setInvite({ ...invite, role: e.target.value })}><option value="adult">adult</option><option value="child">child</option></select><button className="airi-secondary"><UserPlus size={13} /> invite</button></form></>}{message && <div className="airi-inline-notice"><CircleAlert size={13} />{message}</div>}<div className="airi-hint-block"><ShieldCheck size={14} /><span>Every grant, revoke, approval, and deletion is recorded in the audit trail.</span></div></div>;
}

function ConsentRow({ label, active, onGrant, onRevoke }: { label: string; active: boolean; onGrant: () => void; onRevoke: () => void }) { return <div className="airi-consent-row"><span className={active ? 'is-on' : ''}><i />{label}</span>{active ? <button onClick={onRevoke}><Check size={12} /> active</button> : <button onClick={onGrant}><Plus size={12} /> grant</button>}</div>; }
function Status({ status }: { status: string }) { return <span className={`airi-status ${status === 'approved' || status === 'active' ? 'is-green' : status === 'rejected' || status === 'deleted' ? 'is-red' : 'is-warm'}`}><i />{status === 'pending' ? 'pending' : status}</span>; }
